              'ನಿಖರ ಕಾರಣ ಸಂಪೂರ್ಣ ತಿಳಿದಿಲ್ಲ, ಆದರೆ ಆರಂಭಿಕ ಗರ್ಭಾವಸ್ಥೆಯಲ್ಲಿ hCG ಮತ್ತು oestrogen ಮಟ್ಟ ಏರುವುದು ಮುಖ್ಯ ಪಾತ್ರ ವಹಿಸುತ್ತದೆ ಎಂದು ನಂಬಲಾಗಿದೆ. ಹಾರ್ಮೋನ್ ಬದಲಾವಣೆಗಳು ಜಠರ-ಕರುಳಿನ ಕಾಲುವೆ ಮತ್ತು ಮೆದುಳಿನ ವಾಂತಿ ಕೇಂದ್ರವನ್ನು ಪ್ರಭಾವಿಸುತ್ತವೆ, ಇದರಿಂದ ಗರ್ಭಿಣಿ ಮಹಿಳೆಯರು ಕೆಲವು ವಾಸನೆ ಮತ್ತು ರುಚಿಗಳಿಗೆ ಹೆಚ್ಚು ಸೂಕ್ಷ್ಮವಾಗುತ್ತಾರೆ.',
        },
        {
          'title': 'ಆಹಾರ ಸಲಹೆಗಳು',
          'body':
              'ಮೂರು ದೊಡ್ಡ ಊಟದ ಬದಲು ದಿನವಿಡೀ ಸಣ್ಣ, ಆಗಾಗ ಊಟ ತಿನ್ನುವುದು ವಾಕರಿಕೆಯನ್ನು ನಿಯಂತ್ರಿಸಲು ಸಹಾಯ ಮಾಡಬಹುದು. ಒಣ ಬಿಸ್ಕತ್ ಅಥವಾ ಟೋಸ್ಟ್‌ನಂತಹ ಸರಳ, ಒಣ ಆಹಾರ ಸಾಮಾನ್ಯವಾಗಿ ಚೆನ್ನಾಗಿ ಒಗ್ಗಿಕೊಳ್ಳುತ್ತದೆ. ಖಾರ, ಎಣ್ಣೆಯುಕ್ತ ಅಥವಾ ಬಲವಾದ ವಾಸನೆಯ ಆಹಾರ ತಪ್ಪಿಸಿ.',
