          'body':
              'Hyperemesis gravidarum (HG) ಗರ್ಭಾವಸ್ಥೆಯ ಅಸ್ವಸ್ಥತೆಯ ತೀವ್ರ ರೂಪ. ನಿರಂತರ ಮತ್ತು ಅತಿಯಾದ ವಾಕರಿಕೆ ಮತ್ತು ವಾಂತಿಯಿಂದ ನಿರ್ಜಲೀಕರಣ ಮತ್ತು ತೂಕ ಕಳೆದುಕೊಳ್ಳುವಿಕೆ ಉಂಟಾಗುತ್ತದೆ. ಸಾಮಾನ್ಯ ಬೆಳಿಗ್ಗೆಯ ಅಸ್ವಸ್ಥತೆಗಿಂತ ಭಿನ್ನವಾಗಿ, HG ಊಟ, ಕುಡಿತ ಮತ್ತು ದೈನಂದಿನ ಚಟುವಟಿಕೆ ನಡೆಸುವ ಮಹಿಳೆಯ ಸಾಮರ್ಥ್ಯವನ್ನು ತೀವ್ರವಾಗಿ ಪ್ರಭಾವಿಸಬಹುದು.',
        },
        {
          'title': 'ಕಾರಣಗಳು ಮತ್ತು ಅಪಾಯಕಾರಿ ಅಂಶಗಳು',
          'body':
              'ನಿಖರ ಕಾರಣ ಸ್ಪಷ್ಟವಿಲ್ಲ, ಆದರೆ ಇದು ವೇಗವಾಗಿ ಏರುತ್ತಿರುವ hCG ಮಟ್ಟಗಳೊಂದಿಗೆ ಸಂಬಂಧಿಸಿದೆ. ಅವಳಿ ಅಥವಾ ಮೋಲಾರ್ ಗರ್ಭ ಹೊಂದಿರುವ ಮಹಿಳೆಯರಿಗೆ ಹೆಚ್ಚಿನ ಅಪಾಯ ಇರುತ್ತದೆ. HG ಯ ವ್ಯಕ್ತಿಗತ ಅಥವಾ ಕುಟುಂಬ ಇತಿಹಾಸ, ಚಲನ ರೋಗ ಮತ್ತು ಮೈಗ್ರೇನ್ ಸಹ ಸಂಭಾವ್ಯತೆ ಹೆಚ್ಚಿಸುತ್ತವೆ.',
