          'title': 'ಕಾರಣಗಳು',
          'body':
              'ಅತ್ಯಂತ ಸಾಮಾನ್ಯ ಕಾರಣ ಭ್ರೂಣದಲ್ಲಿ ಕ್ರೋಮೋಸೋಮಲ್ ವ್ಯತ್ಯಯ ಆಗಿ ಸಾಮಾನ್ಯ ಬೆಳವಣಿಗೆ ತಡೆಯುತ್ತದೆ. ಇತರ ಅಂಶಗಳಲ್ಲಿ ಹಾರ್ಮೋನ್ ಸಮಸ್ಯೆಗಳು, ಗರ್ಭಾಶಯ ವ್ಯತ್ಯಯಗಳು, ರಕ್ತ ಹೆಪ್ಪುಗಟ್ಟುವ ಅಸ್ವಸ್ಥತೆಗಳು, ನಿಯಂತ್ರಣರಹಿತ ಮಧುಮೇಹ, ಥೈರಾಯ್ಡ್ ರೋಗ ಮತ್ತು ಕೆಲವು ಸೋಂಕುಗಳು ಸೇರಿವೆ.',
