        },
        {
          'title': 'ಕಾರಣಗಳು',
          'body':
              'ಸಂಪೂರ್ಣ mole ತನ್ನ ಆನುವಂಶಿಕ ವಸ್ತು ಕಳೆದುಕೊಂಡ ಮೊಟ್ಟೆಯನ್ನು ಒಂದು ಅಥವಾ ಎರಡು ವೀರ್ಯಗಳು ಫಲವತ್ತಾಗಿಸಿದಾಗ ಸಂಭವಿಸುತ್ತದೆ, ಇದರಿಂದ ತಂದೆಯ ಕ್ರೋಮೋಸೋಮ್‌ಗಳು ಮಾತ್ರ ಇರುತ್ತವೆ. ಭಾಗಶಃ mole ಎರಡು ವೀರ್ಯಗಳು ಸಾಮಾನ್ಯ ಮೊಟ್ಟೆ ಫಲವತ್ತಾಗಿಸಿದಾಗ ಆಗುತ್ತದೆ, ಇದು ಭ್ರೂಣಕ್ಕೆ ಹೆಚ್ಚುವರಿ ಕ್ರೋಮೋಸೋಮ್ ಸೆಟ್ ನೀಡಿ ಸಾಮಾನ್ಯ ಬೆಳವಣಿಗೆ ತಡೆಯುತ್ತದೆ.',
        },
        {
          'title': 'ಲಕ್ಷಣಗಳು',
