        },
        {
          'title': 'ಅನುಸರಣ ನಿಗಾ',
          'body':
              'ಚಿಕಿತ್ಸೆ ನಂತರ, hCG ಮಟ್ಟ ಸಾಮಾನ್ಯಕ್ಕೆ ಮರಳುವ ತನಕ ನಿಯಮಿತ ರಕ್ತ ಮತ್ತು ಮೂತ್ರ ಪರೀಕ್ಷೆ ನಡೆಸಲಾಗುತ್ತದೆ — ಇದು ಕೆಲವು ತಿಂಗಳು ತೆಗೆದುಕೊಳ್ಳಬಹುದು. ಈ ಅನುಸರಣ ಅತ್ಯಂತ ಮಹತ್ವದ್ದು ಏಕೆಂದರೆ ಸ್ವಲ್ಪ ಶೇಕಡ molar ಗರ್ಭಗಳು ನಿರಂತರ ಅಥವಾ ಮಾರಣಾಂತಿಕ ರೂಪಕ್ಕೆ ಬೆಳೆಯಬಹುದು.',
        },
        {
          'title': 'Gestational Trophoblastic Neoplasia (GTN)',
          'body':
              'ಕೆಲವು ಸಂದರ್ಭಗಳಲ್ಲಿ molar ಅಂಗಾಂಶ ಉಳಿಯಬಹುದು ಅಥವಾ ಕ್ಯಾನ್ಸರ್ ಆಗಬಹುದು, ಇದನ್ನು GTN ಎಂದು ಕರೆಯಲಾಗುತ್ತದೆ. ಒಳ್ಳೆ ಸುದ್ದಿ ಏನೆಂದರೆ GTN chemotherapy ಗೆ ತುಂಬಾ ಚೆನ್ನಾಗಿ ಸ್ಪಂದಿಸುತ್ತದೆ, ಮುಂದುವರಿದ ಸಂದರ್ಭಗಳಲ್ಲಿಯೂ ಗುಣಮುಖ ದರ ಶೇ. 95 ಮೀರುತ್ತದೆ.',
        },
        {
          'title': 'ಭವಿಷ್ಯದ ಗರ್ಭಗಳು',
