          'body':
              'ನಿಯಮಿತ ಗರ್ಭಾವಸ್ಥೆಯ ಭೇಟಿಗಳು ನಿಮ್ಮ ಆರೋಗ್ಯ ತಂಡಕ್ಕೆ ಗರ್ಭಾವಸ್ಥೆಯ ಉದ್ದಕ್ಕೂ ನಿಮ್ಮ ಮತ್ತು ನಿಮ್ಮ ಮಗುವಿನ ಆರೋಗ್ಯವನ್ನು ಮೇಲ್ವಿಚಾರಣೆ ಮಾಡಲು ಅನುವು ಮಾಡಿಕೊಡುತ್ತವೆ. ಅವು ಸಂಭಾವ್ಯ ತೊಂದರೆಗಳನ್ನು ಆರಂಭದಲ್ಲಿಯೇ ಪತ್ತೆಹಚ್ಚಲು ಸಹಾಯ ಮಾಡುತ್ತವೆ, ಪ್ರಶ್ನೆಗಳನ್ನು ಕೇಳಲು ಅವಕಾಶ ನೀಡುತ್ತವೆ ಮತ್ತು ಸರಿಯಾದ ಸಮಯದಲ್ಲಿ ಸರಿಯಾದ ಆರೈಕೆ ಪಡೆಯುವುದನ್ನು ಖಚಿತಪಡಿಸುತ್ತವೆ.',
