              'ಗರ್ಭಾವಸ್ಥೆಯ ಮಧುಮೇಹವನ್ನು ತಪಾಸಣೆ ಮಾಡಲು ಸಾಮಾನ್ಯವಾಗಿ 24 ರಿಂದ 28 ವಾರಗಳ ನಡುವೆ glucose tolerance test (OGTT) ಮಾಡಲಾಗುತ್ತದೆ. ಮಧುಮೇಹದ ಕುಟುಂಬ ಇತಿಹಾಸ, ಬೊಜ್ಜು, ಅಥವಾ ಹಿಂದಿನ ದೊಡ್ಡ ಮಗು ಹೊಂದಿರುವ ಮಹಿಳೆಯರಿಗೆ ಮೊದಲೇ ಪರೀಕ್ಷಿಸಬಹುದು.',
