          'body':
              'ವಾಕರಿಕೆ ತಿನ್ನಲು ಕಷ್ಟವಾಗಿಸಿದರೆ, ಸೌಮ್ಯ ಆಹಾರಗಳ ಸಣ್ಣ, ಆಗಾಗ್ಗೆ ಊಟಗಳನ್ನು ಪ್ರಯತ್ನಿಸಿ. ಸಸ್ಯಾಹಾರಿ ಮತ್ತು ವೀಗನ್ ತಾಯಂದಿರು ಎಚ್ಚರಿಕೆಯ ಆಹಾರ ಆಯ್ಕೆಗಳು ಮತ್ತು ಪೂರಕಗಳ ಮೂಲಕ ಸಾಕಷ್ಟು ಕಬ್ಬಿಣ, vitamin B12, ಕ್ಯಾಲ್ಸಿಯಂ ಮತ್ತು ಪ್ರೋಟೀನ್ ಪಡೆಯಲು ವಿಶೇಷ ಗಮನ ನೀಡಬೇಕು.',
