              'ನಿಯಮಿತ ರಕ್ತದೊತ್ತಡ ಪರಿಶೀಲನೆ, ಪ್ರೋಟೀನ್‌ಗಾಗಿ ಮೂತ್ರ ಪರೀಕ್ಷೆ, ಅಂಗ ಕಾರ್ಯವನ್ನು ಮೌಲ್ಯಮಾಪನ ಮಾಡಲು ರಕ್ತ ಪರೀಕ್ಷೆಗಳು ಮತ್ತು ಮಗುವಿನ ಬೆಳವಣಿಗೆಯನ್ನು ಮೇಲ್ವಿಚಾರಣೆ ಮಾಡಲು ultrasound scan ಗಳನ್ನು ಒಳಗೊಂಡಿದೆ. ರಕ್ತದೊತ್ತಡ ಗಮನಾರ್ಹವಾಗಿ ಹೆಚ್ಚಿದ್ದರೆ, ಔಷಧಿಗಳನ್ನು ಸೂಚಿಸಬಹುದು.',
