              'ದೀರ್ಘಕಾಲಿಕ ಅಧಿಕ ರಕ್ತದೊತ್ತಡ, pre-eclampsia, ಹೊಟ್ಟೆಯ ಆಘಾತ, ಧೂಮಪಾನ, cocaine ಬಳಕೆ ಮತ್ತು ಹಿಂದಿನ ಬೇರ್ಪಡುವಿಕೆ ಅಪಾಯಕಾರಿ ಅಂಶಗಳಲ್ಲಿ ಸೇರಿವೆ. ಮುಂದುವರಿದ ತಾಯಿಯ ವಯಸ್ಸು ಮತ್ತು ಬಹು ಗರ್ಭಾವಸ್ಥೆಗಳು ಸಹ ಅಪಾಯವನ್ನು ಹೆಚ್ಚಿಸುತ್ತವೆ.',
