          'body':
              'ಬಹು ಗರ್ಭಾವಸ್ಥೆ ಎಂದರೆ ಒಂದೇ ಸಮಯದಲ್ಲಿ ಎರಡು ಅಥವಾ ಹೆಚ್ಚು ಮಕ್ಕಳನ್ನು ಹೊತ್ತಿರುವುದು. ಅವಳಿಗಳು ಒಂದೇ ಮೊಟ್ಟೆಯಿಂದ (monozygotic/ಸಮರೂಪ) ಅಥವಾ ಎರಡು ಪ್ರತ್ಯೇಕ ಮೊಟ್ಟೆಗಳಿಂದ (dizygotic/ಅಸಮರೂಪ) ಆಗಿರಬಹುದು.',
        },
        {
          'title': 'ಇದು ಹೇಗೆ ಸಂಭವಿಸುತ್ತದೆ',
