        {
          'title': 'Chorionicity ಮತ್ತು ಅದರ ಮಹತ್ವ',
          'body':
              'ಆರಂಭಿಕ ultrasound ಅವಳಿಗಳು ಜರಾಯುವನ್ನು ಹಂಚಿಕೊಳ್ಳುತ್ತಾರೆಯೇ (monochorionic) ಅಥವಾ ಪ್ರತ್ಯೇಕ ಜರಾಯುಗಳನ್ನು ಹೊಂದಿದ್ದಾರೆಯೇ (dichorionic) ಎಂಬುದನ್ನು ನಿರ್ಧರಿಸುತ್ತದೆ. Monochorionic ಅವಳಿಗಳಿಗೆ twin-to-twin transfusion syndrome (TTTS) ಸೇರಿದಂತೆ ತೊಂದರೆಗಳ ಹೆಚ್ಚಿನ ಅಪಾಯವಿದ್ದು, ಹೆಚ್ಚು ಆಗಾಗ್ಗೆ ಮೇಲ್ವಿಚಾರಣೆ ಅಗತ್ಯ.',
        },
        {
          'title': 'ಹೆಚ್ಚಿದ ಅಪಾಯಗಳು',
          'body':
              'ಬಹು ಗರ್ಭಾವಸ್ಥೆಗಳು ಅಕಾಲಿಕ ಹೆರಿಗೆ, pre-eclampsia, ಗರ್ಭಾವಸ್ಥೆಯ ಮಧುಮೇಹ, ರಕ್ತಹೀನತೆ ಮತ್ತು caesarean ಹೆರಿಗೆಯ ಹೆಚ್ಚಿನ ಅಪಾಯಗಳನ್ನು ಹೊಂದಿರುತ್ತವೆ. ಬಹು ಗರ್ಭಾವಸ್ಥೆಗಳಲ್ಲಿ ಮಕ್ಕಳು ಕಡಿಮೆ ಜನನ ತೂಕ ಹೊಂದಿರುವ ಸಾಧ್ಯತೆ ಹೆಚ್ಚು.',
        },
        {
          'title': 'ಗರ್ಭಾವಸ್ಥೆಯ ಆರೈಕೆ',
          'body':
              'ಬಹು ಗರ್ಭಾವಸ್ಥೆಯ ಮಹಿಳೆಯರಿಗೆ ಒಂಟಿ ಮಗುವನ್ನು ಹೊತ್ತಿರುವ ಮಹಿಳೆಯರಿಗಿಂತ ಹೆಚ್ಚು ಆಗಾಗ್ಗೆ ಗರ್ಭಾವಸ್ಥೆಯ ಭೇಟಿಗಳು ಮತ್ತು ultrasound scan ಗಳು ಬೇಕಾಗುತ್ತವೆ. Dichorionic ಅವಳಿಗಳನ್ನು 12 ವಾರಗಳಿಂದ ಪ್ರತಿ ನಾಲ್ಕು ವಾರಗಳಿಗೊಮ್ಮೆ, monochorionic ಅವಳಿಗಳನ್ನು 16 ವಾರಗಳಿಂದ ಪ್ರತಿ ಎರಡು ವಾರಗಳಿಗೊಮ್ಮೆ scan ಮಾಡಲಾಗುತ್ತದೆ.',
        },
        {
          'title': 'ಹೆರಿಗೆ ಯೋಜನೆ',
          'body':
              'ಹೆರಿಗೆಯ ಸಮಯ ಮತ್ತು ವಿಧಾನವು ಅವಳಿ ಗರ್ಭಾವಸ್ಥೆಯ ವಿಧ ಮತ್ತು ತೊಂದರೆಗಳ ಮೇಲೆ ಅವಲಂಬಿತ. ತೊಂದರೆಗಳಿಲ್ಲದ dichorionic ಅವಳಿಗಳನ್ನು ಸುಮಾರು 37 ವಾರಗಳಲ್ಲಿ, monochorionic diamniotic ಅವಳಿಗಳನ್ನು ಸುಮಾರು 36 ವಾರಗಳಲ್ಲಿ ಹೆರಿಗೆ ಮಾಡಲಾಗುತ್ತದೆ.',
        },
        {
          'title': 'ಪ್ರಾಯೋಗಿಕ ತಯಾರಿ',
          'body':
              'ಬಹು ಮಕ್ಕಳಿಗೆ ತಯಾರಿ ಮಾಡುವುದು ಆಹಾರ, ನಿದ್ರೆ ವ್ಯವಸ್ಥೆ ಮತ್ತು ಹೆರಿಗೆ ನಂತರದ ಬೆಂಬಲಕ್ಕಾಗಿ ಹೆಚ್ಚುವರಿ ಯೋಜನೆಯನ್ನು ಒಳಗೊಂಡಿರುತ್ತದೆ. ಸ್ಥಳೀಯ ಬಹು ಜನನ ಗುಂಪುಗಳೊಂದಿಗೆ ಸಂಪರ್ಕ ಸಾಧಿಸುವುದು ಮತ್ತು ಕುಟುಂಬ ಅಥವಾ ಸ್ನೇಹಿತರಿಂದ ಪ್ರಾಯೋಗಿಕ ಸಹಾಯ ವ್ಯವಸ್ಥೆ ಮಾಡುವುದು ಪರಿವರ್ತನೆಯನ್ನು ಸುಗಮಗೊಳಿಸಬಹುದು.',
        },
      ],
    ),

    'thyroid-pregnancy': const EducationTopicData(
      titleEn: 'Thyroid Disorders in Pregnancy',
      titleKn: 'ಗರ್ಭಾವಸ್ಥೆಯಲ್ಲಿ Thyroid ಸಮಸ್ಯೆಗಳು',
      sectionsEn: [
        {
          'title': 'The Thyroid & Pregnancy',
          'body':
