        },
      ],
      sectionsKn: [
        {
          'title': 'ಬೆನ್ನು ನೋವು ಏಕೆ ಸಂಭವಿಸುತ್ತದೆ',
          'body':
              'ಬೆನ್ನು ನೋವು ಗರ್ಭಾವಸ್ಥೆಯ ಅತ್ಯಂತ ಸಾಮಾನ್ಯ ದೂರುಗಳಲ್ಲಿ ಒಂದಾಗಿದ್ದು, 70 ಶೇಕಡಾ ಮಹಿಳೆಯರನ್ನು ಪ್ರಭಾವಿಸುತ್ತದೆ. ಬೆಳೆಯುತ್ತಿರುವ ಗರ್ಭಾಶಯ ಗುರುತ್ವ ಕೇಂದ್ರವನ್ನು ಮುಂದಕ್ಕೆ ಸ್ಥಳಾಂತರಿಸುವುದು, ಹಾರ್ಮೋನ್ ಬದಲಾವಣೆಗಳು ಅಸ್ಥಿರಜ್ಜುಗಳನ್ನು ಸಡಿಲಗೊಳಿಸುವುದು ಮತ್ತು ಹೆಚ್ಚುವರಿ ತೂಕ ಬೆನ್ನೆಲುಬಿನ ಮೇಲೆ ಒತ್ತಡ ಹಾಕುವುದು ಕಾರಣಗಳಾಗಿವೆ.',
        },
        {
          'title': 'ಬೆನ್ನು ನೋವಿನ ವಿಧಗಳು',
          'body':
              'ಸೊಂಟದ ನೋವು (ಕೆಳ ಬೆನ್ನು) ಸೊಂಟದ ಮಟ್ಟ ಅಥವಾ ಮೇಲೆ ಅನುಭವಿಸಲಾಗುತ್ತದೆ ಮತ್ತು ಕಾಲುಗಳಿಗೆ ಹರಡಬಹುದು, ಆದರೆ ಹಿಂಭಾಗದ ಶ್ರೋಣಿ ನೋವು ಸೊಂಟದ ಕೆಳಗೆ ಮತ್ತು ಪೃಷ್ಠಗಳ ಆಳದಲ್ಲಿ ಅನುಭವಿಸಲಾಗುತ್ತದೆ. ಗರ್ಭಾವಸ್ಥೆಯಲ್ಲಿ ಹಿಂಭಾಗದ ಶ್ರೋಣಿ ನೋವು ಹೆಚ್ಚು ಸಾಮಾನ್ಯ.',
        },
        {
