              'ಕ್ರಮೇಣ, ಸಮ್ಮಿತ ಊತ ಸಾಮಾನ್ಯವಾಗಿ ಸಾಮಾನ್ಯ. ಹಠಾತ್ ಅಥವಾ ತೀವ್ರ ಊತ, ವಿಶೇಷವಾಗಿ ಮುಖ ಮತ್ತು ಕೈಗಳ, ತಲೆನೋವು ಅಥವಾ ದೃಷ್ಟಿ ತೊಂದರೆಗಳೊಂದಿಗೆ ಇದ್ದರೆ, pre-eclampsia ಲಕ್ಷಣವಾಗಿರಬಹುದು ಮತ್ತು ತುರ್ತು ವೈದ್ಯಕೀಯ ಗಮನ ಅಗತ್ಯ.',
