    'leg-cramps-pregnancy': const EducationTopicData(
      titleEn: 'Leg Cramps & Restless Legs in Pregnancy',
      titleKn: 'ಗರ್ಭಾವಸ್ಥೆಯಲ್ಲಿ ಕಾಲು ಸೆಳೆತ ಮತ್ತು ಅಶಾಂತ ಕಾಲುಗಳು',
      sectionsEn: [
        {
          'title': 'What Are Leg Cramps?',
          'body':
