              'ಎರಡನೇ ಹಂತ ಗರ್ಭಕಂಠ ಪೂರ್ಣವಾಗಿ ವಿಸ್ತರಿಸಿದಾಗ ಆರಂಭವಾಗಿ ಮಗುವಿನ ಜನನದೊಂದಿಗೆ ಕೊನೆಗೊಳ್ಳುತ್ತದೆ. ಪ್ರತಿ ಸಂಕೋಚನದೊಂದಿಗೆ ನೂಕಲು ಬಲವಾದ ಒತ್ತಾಯ ಅನುಭವಿಸುತ್ತೀರಿ. ನಿಮ್ಮ ಸೂಲಗಿತ್ತಿ ಅಥವಾ ವೈದ್ಯರು ಪರಿಣಾಮಕಾರಿಯಾಗಿ ಯಾವಾಗ ಮತ್ತು ಹೇಗೆ ನೂಕಬೇಕೆಂದು ಮಾರ್ಗದರ್ಶನ ನೀಡುತ್ತಾರೆ.',
