          'body':
              'ಹೆರಿಗೆಯ ಪ್ರೇರಣೆ ಹೆರಿಗೆ ತನ್ನಷ್ಟಕ್ಕೆ ಆರಂಭವಾಗುವ ಮೊದಲೇ ಕೃತಕವಾಗಿ ಆರಂಭಿಸುವ ಪ್ರಕ್ರಿಯೆ. ಗರ್ಭಾವಸ್ಥೆ ಮುಂದುವರಿಸುವುದು ತಾಯಿ ಅಥವಾ ಮಗುವಿಗೆ ಅಪಾಯ ಉಂಟುಮಾಡಿದಾಗ, ಹೆರಿಗೆ ದಿನಾಂಕ ಗಮನಾರ್ಹವಾಗಿ ದಾಟಿದಾಗ, pre-eclampsia ಅಥವಾ ಮಗುವಿನ ಬೆಳವಣಿಗೆಯ ಕಳವಳಗಳಿದ್ದಾಗ ಶಿಫಾರಸು ಮಾಡಬಹುದು.',
