          'title': 'ಪ್ರೇರಣೆ ವಿಧಾನಗಳು',
          'body':
              'Membrane sweep (ಯೋನಿ ಪರೀಕ್ಷೆ ಸಮಯದಲ್ಲಿ ಗರ್ಭಕಂಠವನ್ನು ಹಿಗ್ಗಿಸುವುದು), ಗರ್ಭಕಂಠವನ್ನು ಮೃದುಗೊಳಿಸಲು ಯೋನಿ prostaglandin gel ಅಥವಾ pessary, ಪೊರೆಗಳ ಕೃತಕ ಛಿದ್ರ (ನೀರು ಒಡೆಯುವುದು), ಮತ್ತು ಸಂಕೋಚನಗಳನ್ನು ಉತ್ತೇಜಿಸಲು oxytocin drip ಸಾಮಾನ್ಯ ವಿಧಾನಗಳಲ್ಲಿ ಸೇರಿವೆ.',
        },
        {
          'title': 'ಏನು ನಿರೀಕ್ಷಿಸಬೇಕು',
          'body':
              'ಪ್ರೇರಣೆ ಸಮಯ ತೆಗೆದುಕೊಳ್ಳಬಹುದು, ಕೆಲವೊಮ್ಮೆ ಒಂದರಿಂದ ಎರಡು ದಿನಗಳು, ವಿಶೇಷವಾಗಿ ಗರ್ಭಕಂಠ ಇನ್ನೂ ಸಿದ್ಧವಾಗಿಲ್ಲದಿದ್ದರೆ. ಪ್ರಕ್ರಿಯೆಯ ಉದ್ದಕ್ಕೂ ಹತ್ತಿರದಿಂದ ಮೇಲ್ವಿಚಾರಣೆ ಮಾಡಲಾಗುತ್ತದೆ. ಪ್ರೇರಿತ ಸಂಕೋಚನಗಳು ಹೆಚ್ಚು ತೀವ್ರವಾಗಿರಬಹುದು.',
