              'ನಿಮಗೆ ಸಾಕಷ್ಟು ನೋವು ನಿವಾರಣೆ ಬೇಕಾಗುತ್ತದೆ, ಸಾಮಾನ್ಯವಾಗಿ epidural ಅಥವಾ ಸ್ಥಳೀಯ ಅರಿವಳಿಕೆ. Episiotomy (ಯೋನಿ ತೆರೆಯುವಿಕೆಯನ್ನು ಅಗಲಗೊಳಿಸಲು ಸಣ್ಣ ಕತ್ತರಿಸುವಿಕೆ) ಮಾಡಬಹುದು. ವೈದ್ಯರು ಸಂಕೋಚನದ ಸಮಯದಲ್ಲಿ forceps ಅಥವಾ ventouse ಅನ್ವಯಿಸಿ, ನಿಮ್ಮ ನೂಕುವ ಪ್ರಯತ್ನದೊಂದಿಗೆ ಮಗುವನ್ನು ಹೆರಿಗೆ ಮಾಡುತ್ತಾರೆ.',
