              'ಹೆರಿಗೆ ನಂತರ ಶೀಘ್ರದಲ್ಲೇ ಮೃದು ನಡಿಗೆ ಆರಂಭಿಸಬಹುದು, ಆದರೆ ಹೆಚ್ಚು ಕಠಿಣ ವ್ಯಾಯಾಮ ನೀವು ಸಿದ್ಧರಾಗಿರುವಾಗ ಮತ್ತು ಆರು ವಾರಗಳ ಪ್ರಸವಾನಂತರದ ಪರೀಕ್ಷೆ ಮಾಡಿಸಿಕೊಂಡ ನಂತರ ಕಾಯಬೇಕು. ಶ್ರೋಣಿ ತಳ ವ್ಯಾಯಾಮಗಳನ್ನು ಹುಟ್ಟಿನ ನಂತರ ಶೀಘ್ರದಲ್ಲೇ ಆರಂಭಿಸಬಹುದು ಮತ್ತು ಚೇತರಿಕೆಗೆ ಮುಖ್ಯ.',
