        {
          'title': 'ಹೆರಿಗೆ ನಂತರ ಫಲವತ್ತತೆ',
          'body':
              'ನೀವು ಸ್ತನ್ಯಪಾನ ಮಾಡುತ್ತಿದ್ದರೂ ಸಹ, ಹುಟ್ಟಿನ ಮೂರು ವಾರಗಳಷ್ಟು ಬೇಗ ಅಂಡೋತ್ಪತ್ತಿ ಮರಳಬಹುದು. ನಿಮ್ಮ ಮೊದಲ ಮುಟ್ಟು ಮರಳುವ ಮೊದಲೇ ಗರ್ಭಿಣಿಯಾಗಲು ಸಾಧ್ಯ. ತಕ್ಷಣ ಮತ್ತೆ ಗರ್ಭಧಾರಣೆ ಬಯಸದಿದ್ದರೆ, ಹೆರಿಗೆ ನಂತರ ಶೀಘ್ರದಲ್ಲೇ ಗರ್ಭನಿರೋಧಕ ಪರಿಗಣಿಸುವುದು ಮುಖ್ಯ.',
        },
