        },
        {
          'title': 'ದೀರ್ಘ-ಕಾಲಿಕ ಹಿಂಪಡೆಯಬಹುದಾದ ಗರ್ಭನಿರೋಧಕ',
          'body':
              'Copper IUD, ಹಾರ್ಮೋನಲ್ IUD ಅಥವಾ implant ನಂತಹ LARC ವಿಧಾನಗಳು ಹೆಚ್ಚು ಪರಿಣಾಮಕಾರಿ ಮತ್ತು ಅನುಕೂಲಕರ ಏಕೆಂದರೆ ಅವು ದೈನಂದಿನ ಗಮನ ಅಗತ್ಯವಿಲ್ಲ. ಅವುಗಳನ್ನು ನಿಮ್ಮ ಪ್ರಸವಾನಂತರದ ಪರೀಕ್ಷೆಯಲ್ಲಿ ಅಥವಾ ಮೊದಲೇ ಸೇರಿಸಬಹುದು.',
