              'ನವಜಾತ ಶಿಶು ಸ್ಕ್ರೀನಿಂಗ್ ಪರೀಕ್ಷೆಗಳನ್ನು ಜೀವನದ ಮೊದಲ ಕೆಲವು ದಿನಗಳಲ್ಲಿ ನಡೆಸಲಾಗುತ್ತದೆ, ತಕ್ಷಣ ಸ್ಪಷ್ಟವಾಗಿ ಕಾಣದ ಆದರೆ ಚಿಕಿತ್ಸೆಯಿಲ್ಲದೆ ಗಂಭೀರ ಆರೋಗ್ಯ ಸಮಸ್ಯೆಗಳನ್ನು ಉಂಟುಮಾಡಬಹುದಾದ ಸ್ಥಿತಿಗಳನ್ನು ಗುರುತಿಸಲು. ಲಕ್ಷಣಗಳು ಕಾಣಿಸಿಕೊಳ್ಳುವ ಮೊದಲೇ ಚಿಕಿತ್ಸೆ ಆರಂಭಿಸಲು ಆರಂಭಿಕ ಪತ್ತೆ ಅನುವು ಮಾಡಿಕೊಡುತ್ತದೆ.',
        },
        {
          'title': 'ಹೀಲ್ ಪ್ರಿಕ್ ಪರೀಕ್ಷೆ',
          'body':
              'ಹೀಲ್ ಪ್ರಿಕ್ ಅಥವಾ Guthrie ಪರೀಕ್ಷೆಯನ್ನು ಹುಟ್ಟಿದ 48 ರಿಂದ 72 ಗಂಟೆಗಳ ನಡುವೆ ನಡೆಸಲಾಗುತ್ತದೆ. ಮಗುವಿನ ಹಿಮ್ಮಡಿಯಿಂದ ಕೆಲವು ಹನಿ ರಕ್ತವನ್ನು ವಿಶೇಷ ಕಾರ್ಡ್‌ನಲ್ಲಿ ಸಂಗ್ರಹಿಸಿ phenylketonuria (PKU), ಜನ್ಮಜಾತ hypothyroidism, cystic fibrosis ಮತ್ತು sickle cell ರೋಗ ಸೇರಿದಂತೆ ಹಲವು ಸ್ಥಿತಿಗಳಿಗೆ ಪರೀಕ್ಷಿಸಲಾಗುತ್ತದೆ.',
