              'ಫಾರ್ಮುಲಾ ಬಳಸುತ್ತಿದ್ದರೆ, ಹುಟ್ಟಿನಿಂದಲೇ ಸೂಕ್ತವಾದ ಮೊದಲ ಶಿಶು ಫಾರ್ಮುಲಾ ಆಯ್ಕೆ ಮಾಡಿ. ತಯಾರಿಕೆ ಸೂಚನೆಗಳನ್ನು ಎಚ್ಚರಿಕೆಯಿಂದ ಅನುಸರಿಸಿ: ತಾಜಾ ಕುದಿಸಿ 70 ಡಿಗ್ರಿ ಸೆಲ್ಸಿಯಸ್‌ಗೆ ತಣ್ಣಗಾಗಿಸಿದ ನೀರು ಬಳಸಿ, ಪುಡಿಯನ್ನು ನಿಖರವಾಗಿ ಅಳೆಯಿರಿ ಮತ್ತು ಎರಡು ಗಂಟೆಗಳಲ್ಲಿ ಬಳಸಿ.',
