    'newborn-sleep-safety': const EducationTopicData(
      titleEn: 'Safe Sleep for Newborns',
      titleKn: 'ನವಜಾತ ಶಿಶುಗಳಿಗೆ ಸುರಕ್ಷಿತ ನಿದ್ರೆ',
