              'ಮಗುವಿನೊಂದಿಗೆ ಹಾಸಿಗೆ ಹಂಚಿಕೊಳ್ಳಲು ಆಯ್ಕೆ ಮಾಡಿದರೆ, ನೀವು ಅಥವಾ ನಿಮ್ಮ ಸಂಗಾತಿ ಧೂಮಪಾನ ಮಾಡುತ್ತಿದ್ದರೆ, ಮದ್ಯ ಅಥವಾ ಔಷಧಿ ಸೇವಿಸಿದ್ದರೆ, ಅತ್ಯಂತ ದಣಿದಿದ್ದರೆ, ಅಥವಾ ಮಗು ಅಕಾಲಿಕ ಅಥವಾ ಕಡಿಮೆ ತೂಕವಿದ್ದರೆ ಎಂದಿಗೂ ಹಾಗೆ ಮಾಡಬೇಡಿ. ನಿಮ್ಮ ಹಾಸಿಗೆಗೆ ಜೋಡಿಸುವ ಬೆಡ್‌ಸೈಡ್ ತೊಟ್ಟಿಲು ಅತ್ಯಂತ ಸುರಕ್ಷಿತ ಆಯ್ಕೆ.',
        },
      ],
    ),

    'newborn-vaccinations': const EducationTopicData(
