      sectionsKn: [
        {
          'title': 'ಲಸಿಕೆಗಳು ಏಕೆ ಮುಖ್ಯ',
          'body':
              'ಲಸಿಕೆಗಳು ನಿಮ್ಮ ಮಗುವನ್ನು ಗಂಭೀರ ಮತ್ತು ಮಾರಣಾಂತಿಕ ರೋಗಗಳಿಂದ ರಕ್ಷಿಸುತ್ತವೆ. ಶಿಶುಗಳ ರೋಗನಿರೋಧಕ ವ್ಯವಸ್ಥೆ ಇನ್ನೂ ಬೆಳೆಯುತ್ತಿರುವುದರಿಂದ ಅವರು ಸೋಂಕುಗಳಿಗೆ ವಿಶೇಷವಾಗಿ ದುರ್ಬಲರು. ನಿಮ್ಮ ಮಗುವನ್ನು ಆರೋಗ್ಯವಾಗಿ ಇಡಲು ಲಸಿಕೆ ಅತ್ಯಂತ ಪರಿಣಾಮಕಾರಿ ಮಾರ್ಗಗಳಲ್ಲಿ ಒಂದು.',
