        },
        {
          'title': 'ಲಸಿಕೆ ನಂತರ ಏನು ನಿರೀಕ್ಷಿಸಬಹುದು',
          'body':
              'ಸಾಮಾನ್ಯ ಪ್ರತಿಕ್ರಿಯೆಗಳಲ್ಲಿ ಸೌಮ್ಯ ಜ್ವರ, ಚಡಪಡಿಕೆ ಮತ್ತು ಚುಚ್ಚುಮದ್ದಿನ ಸ್ಥಳದಲ್ಲಿ ಕೆಂಪು ಅಥವಾ ಊತ ಸೇರಿವೆ. ಇವು ರೋಗನಿರೋಧಕ ವ್ಯವಸ್ಥೆ ಪ್ರತಿಕ್ರಿಯಿಸುತ್ತಿರುವ ಸಾಮಾನ್ಯ ಸಂಕೇತಗಳು ಮತ್ತು ಸಾಮಾನ್ಯವಾಗಿ 48 ಗಂಟೆಗಳಲ್ಲಿ ಹೋಗುತ್ತವೆ. ಜ್ವರ ಮತ್ತು ಅಸ್ವಸ್ಥತೆಗೆ ವೈದ್ಯರ ಸಲಹೆ ಮೇರೆಗೆ paracetamol ನೀಡಬಹುದು.',
        },
        {
          'title': 'ದಾಖಲೆಗಳನ್ನು ಕಾಪಾಡುವುದು',
